// AUTO-GENERATED from supabase/functions. Do not edit this file directly.
import {
  sanitizeSource,
  sanitizeVideo,
  type SanitizedSource,
  type SanitizedVideo,
} from "./source-resolution.ts";

export const SOURCE_SYNC_MAX_BATCH = 5;
export const SOURCE_UPLOADS_PAGE_SIZE = 20;
export const YOUTUBE_VIDEO_BATCH_SIZE = 50;
export const INGESTED_METADATA_TTL_MS = 30 * 24 * 60 * 60 * 1000;

export type SourceIngestionState = "disabled" | "idle" | "success" | "partial" | "halted" | "unavailable";
export type ReservationOutcome = "reserved" | "quota_exhausted" | "temporarily_unavailable";
export type ProviderFailure = "not_found" | "transient" | "auth" | "quota" | "circuit";

export interface SourceSyncClaim {
  sourceId: string;
  providerSourceId: string;
  uploadsPlaylistId: string | null;
  sourceMetadataFetchedAt: string | null;
  sourceMetadataExpiresAt: string | null;
}

export interface IngestionServiceState {
  ingestionEnabled: boolean;
  maintenanceMode: boolean;
  haltedUntil: string | null;
}

export interface IngestionChannel extends SanitizedSource {
  uploadsPlaylistId: string;
}

export interface IngestionVideo extends SanitizedVideo {
  providerSourceId: string;
  availability: "active" | "unavailable";
}

export type ProviderResult<T> =
  | { outcome: "success"; data: T }
  | { outcome: ProviderFailure };

export interface SourceIngestionRepository {
  getServiceState(now: Date): Promise<IngestionServiceState>;
  claimDueSources(claimToken: string, limit: number): Promise<readonly SourceSyncClaim[]>;
  reserveProviderQuota(requestCount: number, quotaUnits: number): Promise<ReservationOutcome>;
  upsertSources(channels: readonly IngestionChannel[], fetchedAt: Date, expiresAt: Date): Promise<void>;
  upsertVideos(videos: readonly IngestionVideo[], fetchedAt: Date, expiresAt: Date): Promise<void>;
  markVideosUnavailable(sourceId: string, providerMediaIds: readonly string[]): Promise<void>;
  completeClaim(
    sourceId: string,
    claimToken: string,
    outcome: "success" | "transient_failure" | "definitive_not_found",
    errorCode: string | null,
    uploadsPlaylistId: string | null,
  ): Promise<void>;
  haltIngestion(errorCode: "provider_auth" | "provider_quota" | "provider_circuit_open", until: Date): Promise<void>;
  expireStaleMetadata(limit: number): Promise<void>;
}

export interface YouTubeIngestionProvider {
  getChannels(providerSourceIds: readonly string[]): Promise<ProviderResult<readonly IngestionChannel[]>>;
  getUploadsPage(uploadsPlaylistId: string, maxResults: number): Promise<ProviderResult<readonly string[]>>;
  getVideos(providerMediaIds: readonly string[]): Promise<ProviderResult<readonly IngestionVideo[]>>;
}

export interface SourceIngestionReport {
  state: SourceIngestionState;
  claimed: number;
  succeeded: number;
  failed: number;
  providerRequests: number;
}

type MutableRun = {
  readonly claimToken: string;
  readonly claims: readonly SourceSyncClaim[];
  readonly completed: Set<string>;
  providerRequests: number;
  succeeded: number;
  failed: number;
};

/** Runs one bounded, lease-aware source refresh with no polling or pagination loop. */
export async function executeSourceIngestion(
  repository: SourceIngestionRepository,
  provider: YouTubeIngestionProvider,
  now: Date = new Date(),
  createClaimToken: () => string = () => crypto.randomUUID(),
): Promise<SourceIngestionReport> {
  let serviceState: IngestionServiceState;
  try {
    serviceState = await repository.getServiceState(now);
  } catch {
    return report("unavailable", 0, 0, 0, 0);
  }

  const haltTime = serviceState.haltedUntil ? Date.parse(serviceState.haltedUntil) : Number.NaN;
  if (!serviceState.ingestionEnabled || serviceState.maintenanceMode || (Number.isFinite(haltTime) && haltTime > now.getTime())) {
    return report("disabled", 0, 0, 0, 0);
  }

  const claimToken = createClaimToken();
  let claims: readonly SourceSyncClaim[];
  try {
    claims = await repository.claimDueSources(claimToken, SOURCE_SYNC_MAX_BATCH);
  } catch {
    return report("unavailable", 0, 0, 0, 0);
  }
  if (claims.length === 0) {
    await repository.expireStaleMetadata(50).catch(() => {});
    return report("idle", 0, 0, 0, 0);
  }

  const run: MutableRun = {
    claimToken,
    claims: claims.slice(0, SOURCE_SYNC_MAX_BATCH),
    completed: new Set<string>(),
    providerRequests: 0,
    succeeded: 0,
    failed: 0,
  };
  const ready = new Map<string, { claim: SourceSyncClaim; uploadsPlaylistId: string }>();
  const metadataClaims = run.claims.filter((claim: SourceSyncClaim) => needsSourceMetadata(claim, now));

  if (metadataClaims.length > 0) {
    const channelsResult = await reservedProviderCall(
      repository,
      run,
      () => provider.getChannels(metadataClaims.map((claim: SourceSyncClaim) => claim.providerSourceId)),
    );
    if (channelsResult.outcome !== "success") {
      if (isGlobalStop(channelsResult.outcome)) {
        return await haltAndFinish(repository, run, channelsResult.outcome, now);
      }
      for (const claim of metadataClaims) {
        await failClaim(repository, run, claim, providerErrorCode("channels", channelsResult.outcome));
      }
    } else {
      const channelsById = new Map<string, IngestionChannel>(
        channelsResult.data.map((channel: IngestionChannel) => [channel.providerSourceId, {
          ...sanitizeSource(channel),
          uploadsPlaylistId: channel.uploadsPlaylistId,
        }]),
      );
      try {
        await repository.upsertSources(
          [...channelsById.values()],
          now,
          new Date(now.getTime() + INGESTED_METADATA_TTL_MS),
        );
      } catch {
        for (const claim of metadataClaims) await failClaim(repository, run, claim, "catalog_source_write");
      }

      for (const claim of metadataClaims) {
        if (run.completed.has(claim.sourceId)) continue;
        const channel = channelsById.get(claim.providerSourceId);
        if (!channel) {
          await definitiveClaim(repository, run, claim, "channel_not_found");
          continue;
        }
        ready.set(claim.sourceId, { claim, uploadsPlaylistId: channel.uploadsPlaylistId });
      }
    }
  }

  for (const claim of run.claims) {
    if (!run.completed.has(claim.sourceId) && !ready.has(claim.sourceId) && claim.uploadsPlaylistId) {
      ready.set(claim.sourceId, { claim, uploadsPlaylistId: claim.uploadsPlaylistId });
    }
  }

  const videoOwners = new Map<string, { sourceId: string; providerSourceId: string }>();
  for (const { claim, uploadsPlaylistId } of ready.values()) {
    const uploadsResult = await reservedProviderCall(
      repository,
      run,
      () => provider.getUploadsPage(uploadsPlaylistId, SOURCE_UPLOADS_PAGE_SIZE),
    );
    if (uploadsResult.outcome !== "success") {
      if (isGlobalStop(uploadsResult.outcome)) {
        return await haltAndFinish(repository, run, uploadsResult.outcome, now);
      }
      await failClaim(repository, run, claim, providerErrorCode("uploads", uploadsResult.outcome));
      continue;
    }
    for (const providerMediaId of uploadsResult.data.slice(0, SOURCE_UPLOADS_PAGE_SIZE)) {
      if (!videoOwners.has(providerMediaId)) {
        videoOwners.set(providerMediaId, { sourceId: claim.sourceId, providerSourceId: claim.providerSourceId });
      }
    }
  }

  const sourceVideoFailures = new Set<string>();
  const allVideoIds = [...videoOwners.keys()];
  for (let offset = 0; offset < allVideoIds.length; offset += YOUTUBE_VIDEO_BATCH_SIZE) {
    const batch = allVideoIds.slice(offset, offset + YOUTUBE_VIDEO_BATCH_SIZE);
    const videosResult = await reservedProviderCall(repository, run, () => provider.getVideos(batch));
    if (videosResult.outcome !== "success") {
      if (isGlobalStop(videosResult.outcome)) {
        return await haltAndFinish(repository, run, videosResult.outcome, now);
      }
      for (const videoId of batch) {
        const owner = videoOwners.get(videoId);
        if (owner) sourceVideoFailures.add(owner.sourceId);
      }
      continue;
    }

    const returnedById = new Map<string, IngestionVideo>();
    for (const video of videosResult.data) {
      const owner = videoOwners.get(video.providerMediaId);
      if (!owner || owner.providerSourceId !== video.providerSourceId) continue;
      returnedById.set(video.providerMediaId, {
        ...sanitizeVideo(video),
        providerSourceId: video.providerSourceId,
        availability: video.availability,
      });
    }
    try {
      await repository.upsertVideos(
        [...returnedById.values()],
        now,
        new Date(now.getTime() + INGESTED_METADATA_TTL_MS),
      );
    } catch {
      for (const videoId of batch) {
        const owner = videoOwners.get(videoId);
        if (owner) sourceVideoFailures.add(owner.sourceId);
      }
      continue;
    }

    const missingBySource = new Map<string, string[]>();
    for (const videoId of batch) {
      if (returnedById.has(videoId)) continue;
      const owner = videoOwners.get(videoId);
      if (!owner) continue;
      const ids = missingBySource.get(owner.sourceId) ?? [];
      ids.push(videoId);
      missingBySource.set(owner.sourceId, ids);
    }
    for (const [sourceId, missingIds] of missingBySource) {
      await repository.markVideosUnavailable(sourceId, missingIds).catch(() => {
        sourceVideoFailures.add(sourceId);
      });
    }
  }

  for (const { claim, uploadsPlaylistId } of ready.values()) {
    if (run.completed.has(claim.sourceId)) continue;
    if (sourceVideoFailures.has(claim.sourceId)) {
      await failClaim(repository, run, claim, "videos_unavailable");
    } else {
      await succeedClaim(repository, run, claim, uploadsPlaylistId);
    }
  }

  for (const claim of run.claims) {
    if (!run.completed.has(claim.sourceId)) await failClaim(repository, run, claim, "sync_incomplete");
  }
  await repository.expireStaleMetadata(50).catch(() => {});

  return report(
    run.failed === 0 ? "success" : run.succeeded > 0 ? "partial" : "unavailable",
    run.claims.length,
    run.succeeded,
    run.failed,
    run.providerRequests,
  );
}

function needsSourceMetadata(claim: SourceSyncClaim, now: Date): boolean {
  if (!claim.uploadsPlaylistId || !claim.sourceMetadataFetchedAt || !claim.sourceMetadataExpiresAt) return true;
  const expiresAt = Date.parse(claim.sourceMetadataExpiresAt);
  return !Number.isFinite(expiresAt) || expiresAt <= now.getTime();
}

async function reservedProviderCall<T>(
  repository: SourceIngestionRepository,
  run: MutableRun,
  operation: () => Promise<ProviderResult<T>>,
): Promise<ProviderResult<T>> {
  let reservation: ReservationOutcome;
  try {
    reservation = await repository.reserveProviderQuota(1, 1);
  } catch {
    return { outcome: "circuit" };
  }
  if (reservation !== "reserved") {
    return { outcome: reservation === "quota_exhausted" ? "quota" : "circuit" };
  }
  run.providerRequests += 1;
  try {
    return await operation();
  } catch {
    return { outcome: "transient" };
  }
}

async function succeedClaim(
  repository: SourceIngestionRepository,
  run: MutableRun,
  claim: SourceSyncClaim,
  uploadsPlaylistId: string,
): Promise<void> {
  await repository.completeClaim(claim.sourceId, run.claimToken, "success", null, uploadsPlaylistId);
  run.completed.add(claim.sourceId);
  run.succeeded += 1;
}

async function failClaim(
  repository: SourceIngestionRepository,
  run: MutableRun,
  claim: SourceSyncClaim,
  errorCode: string,
): Promise<void> {
  if (run.completed.has(claim.sourceId)) return;
  await repository.completeClaim(claim.sourceId, run.claimToken, "transient_failure", errorCode, null);
  run.completed.add(claim.sourceId);
  run.failed += 1;
}

async function definitiveClaim(
  repository: SourceIngestionRepository,
  run: MutableRun,
  claim: SourceSyncClaim,
  errorCode: string,
): Promise<void> {
  if (run.completed.has(claim.sourceId)) return;
  await repository.completeClaim(claim.sourceId, run.claimToken, "definitive_not_found", errorCode, null);
  run.completed.add(claim.sourceId);
  run.failed += 1;
}

async function haltAndFinish(
  repository: SourceIngestionRepository,
  run: MutableRun,
  outcome: "auth" | "quota" | "circuit",
  now: Date,
): Promise<SourceIngestionReport> {
  const errorCode = outcome === "auth" ? "provider_auth" : outcome === "quota" ? "provider_quota" : "provider_circuit_open";
  const durationMs = outcome === "circuit" ? 15 * 60 * 1000 : 24 * 60 * 60 * 1000;
  await repository.haltIngestion(errorCode, new Date(now.getTime() + durationMs)).catch(() => {});
  for (const claim of run.claims) {
    if (!run.completed.has(claim.sourceId)) await failClaim(repository, run, claim, errorCode);
  }
  return report("halted", run.claims.length, run.succeeded, run.failed, run.providerRequests);
}

function isGlobalStop(outcome: ProviderFailure): outcome is "auth" | "quota" | "circuit" {
  return outcome === "auth" || outcome === "quota" || outcome === "circuit";
}

function providerErrorCode(resource: "channels" | "uploads", outcome: ProviderFailure): string {
  if (outcome === "not_found") return resource === "channels" ? "channel_not_found" : "uploads_not_found";
  return `${resource}_unavailable`;
}

function report(
  state: SourceIngestionState,
  claimed: number,
  succeeded: number,
  failed: number,
  providerRequests: number,
): SourceIngestionReport {
  return { state, claimed, succeeded, failed, providerRequests };
}
